import sys
import json
import collections

def is_solid(map_id, curr_x, curr_y, dx, dy):
    next_x = curr_x + dx
    next_y = curr_y + dy

    if next_x < 0 or next_y < 0:
        return True

    if map_id == "0_3":
        if next_x > 39 or next_y > 35:
            return True
        if next_y == 28 and 21 <= next_x <= 35:
            return True
        if next_y == 18 and dy == -1 and 32 <= next_x <= 34:
            return True
        if next_x == 35 and 20 <= next_y <= 27:
            return True
        if next_y == 33 and 32 <= next_x <= 38:
            return True
        if next_x == 38 and 19 <= next_y <= 33:
            return True

    elif map_id == "0_5":
        if next_x > 39 or next_y > 29:
            return True
        if next_y == 13 and 20 <= next_x <= 29:
            return True
        if (next_x, next_y) in [(34, 13), (35, 13)]:
            return True
        if next_x == 19 and 18 <= next_y <= 21:
            return True
        if next_y >= 22 and (next_x < 30 or next_x > 32):
            return True

    elif map_id in ["0_12", "0_17"]:
        if next_x > 19 or next_y > 35:
            return True
        # Row 32 fence (Columns 10-19)
        if next_y == 32 and 10 <= next_x <= 19:
            return True
        # Row 13 fence (Columns 13-19)
        if next_y == 13 and 13 <= next_x <= 19:
            return True
        # Defeated trainers (solid obstacles)
        if (next_x, next_y) in [(11, 30), (11, 31)]:
            return True

    elif map_id == "0_25":
        if next_y == 7 and dy == -1 and next_x != 9:
            return True

    return False

def solve(input_data):
    map_id = input_data.get('map_id')
    start_x = int(input_data.get('start_x'))
    start_y = int(input_data.get('start_y'))
    target_x = int(input_data.get('target_x'))
    target_y = int(input_data.get('target_y'))

    directions = [
        ('Up', (0, -1)),
        ('Down', (0, 1)),
        ('Left', (-1, 0)),
        ('Right', (1, 0))
    ]

    queue = collections.deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    while queue:
        cx, cy, path = queue.popleft()

        if cx == target_x and cy == target_y:
            print(json.dumps(path))
            return

        for btn, (dx, dy) in directions:
            nx, ny = cx + dx, cy + dy
            if (nx, ny) not in visited and not is_solid(map_id, cx, cy, dx, dy):
                visited.add((nx, ny))
                queue.append((nx, ny, path + [btn]))

    print(json.dumps([]))

solve(input_data)
